Bash(echo "
// STL Export Function
exportStlButton.addEventListener\(''click'', \(\) => {
    if \(!currentHalftoneData\) {
        alert\(''Please generate a halftone preview first.''\);
        return;
    }

    const maxDepth = parseFloat\(maxDepthInput.value\);
    const stlData = generateSTL\(currentHalftoneData, maxDepth\);

    // Create download
    const blob = new Blob\([stlData], { type: ''application/sla'' }\);
    const url = URL.createObjectURL\(blob\);
    const a = document.createElement\(''a''\);
    a.href = url;
    a.download = \(filenameInput.value || ''halftone''\) + ''.stl'';
    document.body.appendChild\(a\);
    a.click\(\);
    document.body.removeChild\(a\);
    URL.revokeObjectURL\(url\);
}\);")
